import React from 'react';
import './Faqs.css';

const Faqs = () => {
  return (
    <div className="faqs-container">
      <h1>Frequently Asked Questions</h1>
      <div className="faq-item">
        <h2>What is the return policy?</h2>
        <p>You can return any item within 30 days of purchase.</p>
      </div>
      <div className="faq-item">
        <h2>How do I track my order?</h2>
        <p>You can track your order from the "My Orders" page.</p>
      </div>
      <div className="faq-item">
        <h2>Do you ship internationally?</h2>
        <p>We currently only ship within the country.</p>
      </div>
    </div>
  );
};

export default Faqs;
